nts',NULL,533,1,'2014-07-01 13:20:38',NULL),(534,529,86,2,'Are the fraud and abuse policies and procedures periodicallly audited to confirm they are being followed',NULL,534,1,'2014-07-01 13:20:38',NULL),(535,529,86,2,'Does the practice have \"financial relationships\" with referring physicians or other health care organizations',NULL,535,1,'2014-07-01 13:20:39',NULL),(536,529,86,2,'Do the \"financial arrangements\" include remuneration for providing the referrals or recommendations',NULL,536,1,'2014-07-01 13:20:39',NULL),(537,529,86,2,'Do the fraud and abuse policies and procedures provide for appropriate sanctions for workforce members who violate those policies',NULL,537,1,'2014-07-01 13:20:40',NULL),(538,529,86,2,'Do the fraud and abue policies provide for appropriate record retention ',NULL,538,1,'2014-07-01 13:20:40',NULL),(539,529,86,2,'Does the practiceknow what to do if a fraud and/or abuse incident occurs',NULL,539,1,'2014-07-01 13:20:43',NULL),(540,419,75,2,'Are patients aware that they can make such a request - is it in the practice\'s Notice of Privacy Practices',NULL,540,1,'2014-07-03 21:57:49',NULL),(541,NULL,87,2,'Is there a risk of the practice, and individuals within the practice, incurring substantial monetary civil penalties for breach violations',NULL,NULL,1,'2014-07-03 22:18:52',NULL),(542,541,87,2,'Do providers, management and staff know the penalty structure in case of a breach violation',NULL,NULL,1,'2014-07-03 22:19:00',NULL),(543,541,87,2,'Does the practice have a policy and procedure for tracking level of care taken in managing breach violations',NULL,NULL,1,'2014-07-03 22:19:37',NULL),(544,541,87,2,'Are those policies and procedures documented and applicable users trained',NULL,NULL,1,'2014-07-03 22:19:46',NULL),(545,541,87,2,'Does the practice know that there are affirmative defenses available for a breach violation',NULL,NULL,1,'2014-07-03 22:19:54',NULL),(546,541,87,2,'Does the practice know the affirmative defenses for breach violation',NULL,NULL,1,'2014-07-03 22:19:59',NULL);

/*Table structure for table `assessments_questions_categories` */

DROP TABLE IF EXISTS `assessments_questions_categories`;

CREATE TABLE `assessments_questions_categories` (
  `aqc_id` int(11) NOT NULL AUTO_INCREMENT,
  `aqc_parent_id` int(11) DEFAULT NULL,
  `aqc_name` varchar(255) DEFAULT NULL,
  `aqc_citation` varchar(255) DEFAULT NULL,
  `aqc_specification` varchar(255) DEFAULT NULL,
  `aqc_description` text,
  `aqc_active` tinyint(1) DEFAULT '1',
  `aqc_create_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `aqc_update_date` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`aqc_id`)
) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8 CHECKSUM=1 DELAY_KEY_WRITE=1 ROW_FORMAT=DYNAMIC;

/*Data for the table `assessments_questions_categories` */

insert  into `assessments_questions_categories`(`aqc_id`,`aqc_parent_id`,`aqc_name`,`aqc_citation`,`aqc_specification`,`aqc_description`,`aqc_active`,`aqc_create_date`,`aqc_update_date`) values (1,NULL,'General Rules','§164.306(d)(1) and §164.306(d)(2)','Implementation Specifications','A covered entity must comply will the standards as provided',1,'2014-06-25 20:27:57','0000-00-00 00:00:00'),(2,NULL,'Administrative Safeguards','§164.308(a)(1)(ii)(A)','Risk Analysis','Conduct an accurate and thorough assessment of the potential risks and vulnerabilities to the confidentiality, integrity and availability of ePHI held by the practice',1,'2014-06-25 20:31:47','0000-00-00 00:00:00'),(3,2,'Administrative Safeguards','§164.308(a)(1)(ii)(B)','Risk Management','Implement security measures sufficient to reduce risks and vulnerabilities to a reasonable and appropriate level',1,'2014-06-25 20:32:46','0000-00-00 00:00:00'),(4,NULL,'Administrative Safeguards','§164.308(a)(1)(ii)(C)','Sanction Policy','Apply appropriate sanctions against workforce members who fail to comply with security policies and procedures',1,'2014-06-25 20:33:08','0000-00-00 00:00:00'),(5,NULL,'Administrative Safeguards','§164.308(a)(1)(ii)(D)','Information System Activity Review','Implement procedures to regularly review records of information system activity and security incident tracking reports',1,'2014-06-25 20:36:33','0000-00-00 00:00:00'),(6,NULL,'Administrative Safeguards','§164.308(a)(2) ','Chief Security Officer','Identify the person who is responsible for the development and implementation of the policies and procedure',1,'2014-06-25 20:37:10','0000-00-00 00:00:00'),(7,NULL,'Administrative Safeguards','§164.308(a)(3)(ii)(A)','Authorization and/or Supervision','Implement procedures for the authorization and/or supervision of workforce members who work with ePHI or in locations ',1,'2014-06-25 20:37:55','0000-00-00 00:00:00'),(8,NULL,'Administrative Safeguards','§164.308(a)(3)(ii)(B)','Workforce Clearance Procedure','Implement procedures to determine that the access of a workforce member to ePHI is appropriate',1,'2014-06-25 20:38:33','0000-00-00 00:00:00'),(9,NULL,'Administrative Safeguards','§164.308(a)(3)(ii)(C) ','Termination Procedure','Implement procedures for terminating access to ePHI when the employment of a workforce member end or the workforce member\'s clearance changes',1,'2014-06-25 20:39:09','0000-00-00 00:00:00'),(10,NULL,'Administrative Safeguards','§164.308(a)(4)(ii)(A) ','Isolating Health Care Clearinghouse Functions ','If a clearinghouse is part of the health care organization\'s function, the clearinghouse must implement  policies and procedures that protect the ePHI from unauthorized access',1,'2014-06-25 20:39:44','0000-00-00 00:00:00'),(11,NULL,'Administrative Safeguards','§164.308(a)(4)(ii)(B) ','Access Authorization','Implement policies and procedures for granting access to ePHI through access to a workstation, transaction, program, process or other program',1,'2014-06-25 20:41:47','0000-00-00 00:00:00'),(12,11,'Administrative Safeguards','§164.308(a)(4)(ii)(C) ','Access Establishment and Modification','Implement policies and procedures that, based upon the entity\'s access authorization policies, establish, document, review and modify a user\'s right of access to a workstation, transaction, program or process',1,'2014-06-25 20:42:28','0000-00-00 00:00:00'),(13,NULL,'Administrative Safeguards','§164.308(a)(5)(ii)(A) ','Security Reminders','Periodic security updates',1,'2014-06-25 20:43:23','0000-00-00 00:00:00'),(14,NULL,'Administrative Safeguards','§164.308(a)(5)(ii)(B)','Protection from Malicious Software','Procedures for guarding against, detecting and reporting malicious software',1,'2014-06-25 20:43:24','0000-00-00 00:00:00'),(15,NULL,'Administrative Safeguards','§164.308(a)(5)(ii)(C)','Log-in Monitoring','Procedures for monitoring log-in attempts and reporting discrepancies',1,'2014-06-25 20:45:07','0000-00-00 00:00:00'),(16,NULL,'Administrative Safeguards','§164.308(a)(5)(ii)(D) ','Password Management ','Procedures for creating, changing and safeguarding passwords',1,'2014-06-25 20:45:47','0000-00-00 00:00:00'),(17,NULL,'Administrative Safeguards','§164.308(a)(6)(ii) ','Security Incidents - Response and Reporting ','Implement policies and procedures to identify and respond to suspected or known security incidents, mitigate to the extent practicable, harmful effects of security incidents known by the covered entity; and document security incidents',1,'2014-06-25 20:45:49','0000-00-00 00:00:00'),(18,NULL,'Administrative Safeguards','§164.308(a)(7)(ii)(A) ','Data Backup Plan','Establish and implement procedures to create and maintain retrievable exact copies of ePHI',1,'2014-06-25 20:46:30','0000-00-00 00:00:00'),(19,NULL,'Administrative Safeguards','§164.308(a)(7)(ii)(B) ','Disaster Recovery Plan ','Establish (and implement as needed) procedures to restore any lost data',1,'2014-06-25 20:48:15','0000-00-00 00:00:00'),(20,NULL,'Administrative Safeguards','§164.308(a)(7)(ii)(C) ','Emergency Mode Operation Plan','Establish (and implement as needed) procedures to enable continuation of critical business processes for protection of the security of ePHI while operating in an emergency mode',1,'2014-06-25 20:48:16','0000-00-00 00:00:00'),(21,NULL,'Administrative Safeguards','§164.308(a)(7)(ii)(D) ','Testing and Revision Procedures ','Implement procedures for the periodic testing and revision of contingency plans',1,'2014-06-25 20:48:47','0000-00-00 00:00:00'),(22,NULL,'Administrative Safeguards','§164.308(a)(7)(ii)(E)','Applications and Data Criticality Analysis','Assess the relative criticality of specific applications and data in support of other contingency plan components',1,'2014-06-25 20:49:29','0000-00-00 00:00:00'),(23,NULL,'Administrative Safeguards','§164.308(a)(8)(4) ','Written contract or other arrangement','Document the satisfactory assurances required by this regulation that the business associate meets the applicable requirements',1,'2014-06-25 20:50:02','0000-00-00 00:00:00'),(24,NULL,'Physical Safeguards','§164.310(a)(2)(i) ','Contingency Operations','Establish (and implement as needed) procedures that allow facility access in support of restoration of lost data under the disaster recovery plan and emergency mode operations plan in the event of an emergency',1,'2014-06-25 20:50:39','0000-00-00 00:00:00'),(25,NULL,'Physical Safeguards','§164.310(a)(2)(ii) ','Facility Security Plan','Implement policies and procedures to safeguard the facility and the equipment from unauthorized access, tampering and theft',1,'2014-06-25 20:51:07','0000-00-00 00:00:00'),(26,NULL,'Physical Safeguards','§164.310(a)(2)(iii) ','Access Control and Validation Procedures','Implement policies and procedures to control and validate a person\'s access to facilities based on their role or function and control access to software programs for testing and revisions',1,'2014-06-25 20:51:07','0000-00-00 00:00:00'),(27,NULL,'Physical Safeguards','§164.310(a)(2)(iv)','Maintenance Records ','Implement policies and procedures to document repairs and modifications to the physical components of the facility which are related to security',1,'2014-06-25 20:51:08','0000-00-00 00:00:00'),(28,NULL,'Physical Safeguards','§164.310(b)','Workstation Use','Implement policies and procedures that specify the proper functions to be performed, the manner in which those functions are to be performed and the physical attributes of the surroundings of a specific workstation or class of workstations that can access ePHI',1,'2014-06-25 20:51:09','0000-00-00 00:00:00'),(29,NULL,'Physical Safeguards','§164.310(c)','Workstation Security','Implement physical safeguards for all workstations, and other devices, that access ePHI to restrict access to authorized users',1,'2014-06-25 20:54:21','0000-00-00 00:00:00'),(30,NULL,'Physical Safeguards','§164.310(d)(2)(i)','Disposal','Implement policies and procedures to address the final disposition of ePHI and/or the hardware or electronic media on which it is stored',1,'2014-06-25 20:54:42','0000-00-00 00:00:00'),(31,NULL,'Physical Safeguards','§164.310(d)(2)(ii)','Media Use','Implement policies and procedures for removal of ePHI from electronic media before the media is made available for re-use',1,'2014-06-25 20:53:47','0000-00-00 00:00:00'),(32,NULL,'Physical Safeguards','§164.310(d)(2)(iii)','Accountability','Maintain a record of the movements of hardware and electronic media and any person responsible for the movement',1,'2014-06-25 20:53:47','0000-00-00 00:00:00'),(33,NULL,'Physical Safeguards','§164.310(d)(2)(iv)','Data Backup and Storage ','Create and retrievable copy of ePHI, when needed, before movement of equipment',1,'2014-06-25 20:53:49','0000-00-00 00:00:00'),(34,NULL,'Technical Safeguards','§164.312(a)(2)(i)','Unique User Identification','Assign a unique name and/or number for identifying and tracking user identity',1,'2014-06-25 20:56:21','0000-00-00 00:00:00'),(35,NULL,'Technical Safeguards','§164.312(a)(2)(ii)','Emergency Access Procedure','Establish (and implement as needed) procedures for obtaining necessary ePHI during an emergency',1,'2014-06-25 20:56:22','0000-00-00 00:00:00'),(36,NULL,'Technical Safeguards','§164.312(a)(2)(iii)','Automatic Logoff','Implement electronic procedures that terminate an electronic session after a predetermined time of inactivity',1,'2014-06-25 20:56:22','0000-00-00 00:00:00'),(37,NULL,'Technical Safeguards','§164.312(a)(2)(iv)','Encryption and Decryption','Implement a mechanism to encrypt and decrypt ePHI',1,'2014-06-25 20:56:23','0000-00-00 00:00:00'),(38,NULL,'Technical Safeguards','§164.312(b) ','Audit Controls','Implement hardware, software and/or procedural mechanisms that record and examine activity in information systems that contain ePHI',1,'2014-06-25 20:56:24','0000-00-00 00:00:00'),(39,NULL,'Technical Safeguards','§164.312(c)(1) ','Integrity','Implement policies and procedures to protect ePHI from improper alteration or destruction',1,'2014-06-25 20:58:57','0000-00-00 00:00:00'),(40,NULL,'Technical Safeguards','§164.312(c)(2)','Mechanism to Authenticate ePHI','Implement electronic mechanisms to corroborate that ePHI has not been altered or destroyed in an unauthorized manner',1,'2014-06-25 20:58:58','0000-00-00 00:00:00'),(41,NULL,'Technical Safeguards','§164.312(d) ','Person or entity authentication','Implement procedures to verify that a person or entity seeking access to ePHI is the one claimed',1,'2014-06-25 20:58:59','0000-00-00 00:00:00'),(42,NULL,'Technical Safeguards','§164.312(e)(2)(i)','Integrity Controls','Implement security measures to ensure that electronically transmitted ePHI is not properly modified without detection until disposed of',1,'2014-06-25 20:58:59','0000-00-00 00:00:00'),(43,NULL,'Technical Safeguards','§164.312(e)(2)(ii) ','Encryption','Implement a mechanism to encrypt ePHI whenever being transmitted',1,'2014-06-25 20:59:01','0000-00-00 00:00:00'),(44,NULL,'Organizational Requirements','§164.314(a)(1)(ii)','Business Associate contracts','A covered entity is not in compliance if the covered entity knows of a pattern of an activity or practice of the business associate that constituted a material breach of the business associate\'s obligations unless the covered entity took reasonable steps to cure the breach ',1,'2014-06-25 21:02:37','0000-00-00 00:00:00'),(45,NULL,'Organizational Requirements','§164.314(a)(2)(i)A), (B), (C), (D) ','Business Associate contracts ','Implementation - Business Associate Agreements must provide that the Business Associate will include the following requirements',1,'2014-06-25 21:02:08','0000-00-00 00:00:00'),(46,NULL,'Policies and Procedures and Documentation Requirements','§164.316 (a) ','Policies and Procedures and Documentation Requirements','Implement reasonable and appropriate policies to comply with the standards, implementation specifications or other requirements of the regulation',1,'2014-06-25 21:02:09','0000-00-00 00:00:00'),(47,NULL,'Policies and Procedures and Documentation Requirements','§164.316 (b)(2)(i)','Time Limit','Retain the required documentation for 6 years from the date of the creation',1,'2014-06-25 21:02:10','0000-00-00 00:00:00'),(48,NULL,'Policies and Procedures and Documentation Requirements','§164.316 (b)(2)(ii) ','Availability','Make documentation available to those responsible for implementing the procedures to which the documentation pertains',1,'2014-06-25 21:02:10','0000-00-00 00:00:00'),(49,NULL,'Policies and Procedures and Documentation Requirements','§164.316 (b)(2)(iii) ','Updates','Periodically review documentation and update as needed in response to environmental or operational changes affecting security of the ePHI',1,'2014-06-25 21:02:11','0000-00-00 00:00:00'),(50,NULL,'Impact of the Use of Mobile Devices on HIPAA Compliance',NULL,NULL,NULL,1,'2014-06-25 21:02:12','0000-00-00 00:00:00'),(51,NULL,'Impact of Social Media on HIPAA Security',NULL,NULL,NULL,1,'2014-06-25 21:05:35','0000-00-00 00:00:00'),(52,NULL,'BEST PRACTICES',NULL,NULL,'There is no specific HIPAA/HITECH regulation that describes that health care organization must use BEST PRACTICES in achieving HIPAA/ HITECH compliance.   It is recognized that using BEST PRACTICES for identifying areas that require attention and the efforts to comply efficiently enable compliance and demonstrate intent to comply with the regulations',1,'2014-07-01 11:46:54','0000-00-00 00:00:00'),(53,NULL,'General Rules','§164.502(a) ','Uses and Disclosures of Protected Health Information ','A covered entity may not use or disclose protected health information except to the individual, for treatment, payment or operations, or, in other cases, without individual consent, or other allowable disclosures to government entities',1,'2014-07-01 11:53:32','0000-00-00 00:00:00'),(54,NULL,'General Rules','§164.502(b), §164.514','Uses and Disclosures of Protected Health Information ','A covered entity may only disclose the minimum information needed to accomplish the intended purpose',1,'2014-07-01 11:56:44','0000-00-00 00:00:00'),(55,NULL,'General Rules','§164.502(d)','Uses and Disclosures of Protected Health Information ','Uses and disclosures of de-identified protected health information',1,'2014-07-01 11:57:05','0000-00-00 00:00:00'),(56,NULL,'General Rules','§164.502(e), §164.504(e)(1), §164.308, §164.314(a)(i and ii) ','Uses and Disclosures of Protected Health Information ','A covered entity may disclose electronic protected health information to a business associate or allow a business associate to create or receive electronic protected health information on its behalf ',1,'2014-07-01 12:00:53','0000-00-00 00:00:00'),(57,NULL,'Organizational Requirements','§164.504(a)','Uses and Disclosures of Protected Health Information','Is the practice a hybrid entity?  Does the practice provide health care services for providers, management and employees in the practice ',1,'2014-07-01 12:04:35','0000-00-00 00:00:00'),(58,NULL,NULL,'§164.508','Uses and Disclosures for an Authorization is Required','Is the patient protected health information secure from unauthorized disclosure without a proper authorization',1,'2014-07-01 12:16:48','0000-00-00 00:00:00'),(59,NULL,NULL,'§164.512(a)','Uses and Disclosures for which consent, an authorization, or opportunity to agree or object is not required','A covered entity may disclose PHI to extent that such use or disclosure is required by law ',1,'2014-07-01 12:19:18','0000-00-00 00:00:00'),(60,NULL,NULL,'§164.512(b) ','Uses and Disclosures for which consent, an authorization, or opportunity to agree or object is not required','A covered entity may disclose PHI to public health activities',1,'2014-07-01 12:20:50','0000-00-00 00:00:00'),(61,NULL,NULL,'§164.512(c)','Uses and Disclosures for which consent, an authorization, or opportunity to agree or object is not required','A covered entity may disclose PHI about an individual whom the covered entity reasonably believes to be a victim of abuse, neglect or domestic violence to a government authority',1,'2014-07-01 12:22:19','0000-00-00 00:00:00'),(62,NULL,NULL,'§164.512(d)','Uses and Disclosures for which consent, an authorization, or opportunity to agree or object is not required','A covered entity may disclose PHI about an individual to a health oversight agency for oversight activities authorized by law',1,'2014-07-01 12:24:04','0000-00-00 00:00:00'),(63,NULL,NULL,'§164.512(e) ','Uses and Disclosures for which consent, an authorization, or opportunity to agree or object is not required','A covered entity may disclose PHI about an individual for judicial and administrative proceedings',1,'2014-07-01 12:25:28','0000-00-00 00:00:00'),(64,NULL,NULL,'§164.512(f)','Uses and Disclosures for which consent, an authorization, or opportunity to agree or object is not required','A covered entity may disclose PHI about an individual for law enforcement purposes',1,'2014-07-01 12:25:39','0000-00-00 00:00:00'),(65,NULL,NULL,'§164.512(g) ','Uses and Disclosures for which consent, an authorization, or opportunity to agree or object is not required','A covered entity may disclose PHI about a deceased individual to a coroner or medical examiner for the purposes of identifying a deceased person or determining the cause of death',1,'2014-07-01 12:25:58','0000-00-00 00:00:00'),(66,NULL,NULL,'§164.512(h) ','Uses and Disclosures for which consent, an authorization, or opportunity to agree or object is not required','A covered entity may disclose PHI about an individual to an organ procurement organization for the purpose of facilitating a donation or transplantation',1,'2014-07-01 12:29:16','0000-00-00 00:00:00'),(67,NULL,NULL,'§164.512(i)','Uses and Disclosures for which consent, an authorization, or opportunity to agree or object is not required','A covered entity may disclose PHI about an individual for research regardless of the source of funding',1,'2014-07-01 12:29:24','0000-00-00 00:00:00'),(68,NULL,NULL,'§164.512(j)','Uses and Disclosures for which consent, an authorization, or opportunity to agree or object is not required','A covered entity may disclose PHI about an individual regarding applicable laws of ethical conduct to prevent a threat or apprehend an individual',1,'2014-07-01 12:29:42','0000-00-00 00:00:00'),(69,NULL,NULL,'§164.512(k) ','Uses and Disclosures for which consent, an authorization, or opportunity to agree or object is not required','A covered entity may disclose PHI about an individual for specialized government functions such as military or veterans activities or armed forces use deemed necessary bu appropriate military command authorities',1,'2014-07-01 12:29:56','0000-00-00 00:00:00'),(70,NULL,NULL,'§164.512(l)','Uses and Disclosures for which consent, an authorization, or opportunity to agree or object is not required','A covered entity may disclose PHI about an individual to comply with laws relating to workers\' compensation or other similar programs',1,'2014-07-01 12:30:08','0000-00-00 00:00:00'),(71,NULL,NULL,'§164.514(b)','Other Requirements Related to Used and Disclosures of Protected Health Information','Requirements for de-identification of protected health information',1,'2014-07-01 12:35:16','0000-00-00 00:00:00'),(72,NULL,NULL,'§164.514(d)','Other Requirements Related to Used and Disclosures of Protected Health Information','Minimum necessary uses of protected health information',1,'2014-07-01 12:36:24','0000-00-00 00:00:00'),(73,NULL,NULL,'§164.514(f)','Other Requirements Related to Used and Disclosures of Protected Health Information','Fundraising',1,'2014-07-01 12:36:38','0000-00-00 00:00:00'),(74,NULL,NULL,'§164.520','Notice of Privacy Practices for Protected Health Information','Does the practice have a Notice of Privacy Practices that describes their privacy and security procedures and meets the standards required in the regulations',1,'2014-07-01 12:41:20','0000-00-00 00:00:00'),(75,NULL,NULL,'§164.522(a)(1)(i)','Rights to Request Privacy Protection for Protected Health Information','A covered entity must permit the individual to restrict the uses or disclosures of PHI for treatment, payment of operations',1,'2014-07-01 12:44:17','0000-00-00 00:00:00'),(76,NULL,NULL,'§164.522(b)(1)','Rights to Request Privacy Protection for Protected Health Information','Confidential Communications Requirements',1,'2014-07-01 12:44:46','0000-00-00 00:00:00'),(77,NULL,NULL,'Section 13405(a) of HITECH ','Rights to Request Privacy Protection for Protected Health Information','Restrictions on certain disclosures and sales of health information - an individual may request under §164.522(a)(1)(i)(A) that the covered entity restrict disclosure of protected health information regarding the payment or health care operations if the individual has paid for the treatment out of pocket',1,'2014-07-01 12:45:15','0000-00-00 00:00:00'),(78,NULL,NULL,'§164.524(a)(1)','Access of Individuals to Protected Health Information','An individual has the right of access to inspect and obtain a copy of protected health information about the individual',1,'2014-07-01 12:48:59','0000-00-00 00:00:00'),(79,NULL,NULL,'§164.526(b)','Amendment of Protected Health Information','An individual has the right to request the covered entity to amend their protected health information',1,'2014-07-01 12:49:26','0000-00-00 00:00:00'),(80,NULL,NULL,'§164.528 ','Accounting of Disclosures of Protected Health Information','An individual has the right to an accounting of unauthorized disclosures of protected health information for a period of 6 years prior to the date of the request',1,'2014-07-01 12:52:43','0000-00-00 00:00:00'),(81,NULL,NULL,'Section 13405(c)(1) of HITECH','Accounting of Disclosures of Protected Health Information','Accounting for Disclosures of Protected Health Information - in the case the practice uses an electronic health record for protected health information regarding §164.528 a individual shall have the right to receive an accounting of disclosures of ePHI for a treatment, payment or operations for a period of three years',1,'2014-07-01 12:53:09','0000-00-00 00:00:00'),(82,NULL,NULL,'§164.530','Administrative Requirements','A covered entity must assign a Chief Privacy Officer responsibility for developing, implementing and administering the HIPAA regulations',1,'2014-07-01 12:56:15','0000-00-00 00:00:00'),(83,NULL,NULL,'164.530(a)','Administrative Requirements','A covered entity must reasonably safeguard protected health information from any intentional or unintentional use or disclosure to an unauthorized individual',1,'2014-07-01 12:57:08','0000-00-00 00:00:00'),(84,NULL,NULL,'§164.400 (HITECH - Breach Notification)','HITECH SPECIFICATIONS','Notification responsibilities in the event of an acquisition, access, use or disclosure of protected health information in a manner not permitted by HIPAA which compromises the security or privacy of the protected health information',1,'2014-07-01 13:08:01','0000-00-00 00:00:00'),(85,NULL,NULL,'42 CFR Parts 412,413, 422, 495 \"Meaningful Use\"','HITECH SPECIFICATIONS','A health care provider must demonstrate \"meaningful use\" of an electronic medical records system to qualify for certain payment schedules from Medicare and Medicaid',1,'2014-07-01 13:09:06','0000-00-00 00:00:00'),(86,NULL,NULL,NULL,'Title II - Preventing Health Care Fraud and Abuse','Subtitles A through E - Fraud and Abuse - HHS to establish programs to control, investigate and monitor health care fraud and abuse, establish a program for data collection for reporting adverse actions…against health care providers, and amend the criminal code regarding health care fraud and abuse',1,'2014-07-01 13:18:19','0000-00-00 00:00:00'),(87,NULL,NULL,'§160.400','(HITECH -Enforcement)','The  civil monetary penalties associated  with a breach violation depend upon the level of care taken by the covered entity',1,'2014-07-03 22:18:00','0000-00-00 00:00:00');

/*Table structure for table `assessments_questions_options` */

DROP TABLE IF EXISTS `assessments_questions_options`;

CREATE TABLE `assessments_questions_options` (
  `aqo_id` int(11) NOT NULL AUTO_INCREMENT,
  `aqo_aq_id` int(11) DEFAULT NULL,
  `aqo_title` varchar(255) DEFAULT NULL,
  `aqo_order` int(11) DEFAULT NULL,
  `aqo_risk_score` decimal(10,2) DEFAULT NULL,
  `aqo_active` tinyint(1) DEFAULT '1',
  `aqo_create_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `aqo_update_date` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`aqo_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1613 DEFAULT CHARSET=utf8;

